class Solution {
public:
    int numberWays(vector<vector<int>>& hats) {
        int n = hats.size();
        const int MOD = 1e9 + 7;
        vector<vector<int>> hat_to_people(41);
        for (int p = 0; p < n; ++p) {
            for (int h : hats[p]) hat_to_people[h].push_back(p);
        }
        vector<int> dp(1 << n, 0);
        dp[0] = 1;
        for (int h = 1; h <= 40; ++h) {
            vector<int> next_dp = dp;
            for (int p : hat_to_people[h]) {
                int bit = 1 << p;
                for (int mask = (1 << n) - 1; mask >= 0; --mask) {
                    if (!(mask & bit)) {
                        next_dp[mask | bit] = (next_dp[mask | bit] + dp[mask]) % MOD;
                    }
                }
            }
            dp = move(next_dp);
        }
        return dp[(1 << n) - 1];
    }
};

class Solution {
    public int numberWays(List<List<Integer>> hats) {
        int n = hats.size();
        int MOD = 1_000_000_007;
        List<Integer>[] hatToPeople = new List[41];
        for (int i = 0; i <= 40; ++i) hatToPeople[i] = new ArrayList<>();
        for (int p = 0; p < n; ++p) {
            for (int h : hats.get(p)) hatToPeople[h].add(p);
        }
        int[] dp = new int[1 << n];
        dp[0] = 1;
        for (int h = 1; h <= 40; ++h) {
            int[] nextDp = dp.clone();
            for (int p : hatToPeople[h]) {
                int bit = 1 << p;
                for (int mask = (1 << n) - 1; mask >= 0; --mask) {
                    if ((mask & bit) == 0) {
                        nextDp[mask | bit] = (nextDp[mask | bit] + dp[mask]) % MOD;
                    }
                }
            }
            dp = nextDp;
        }
        return dp[(1 << n) - 1];
    }
}

